import{_ as r,o as a,c as e,ai as o}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Agent 面试 · 项目讲述模板","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/project-story.md","filePath":"guide/agent/project-story.md"}'),d={name:"guide/agent/project-story.md"};function n(i,t,l,s,h,g){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="agent-面试-·-项目讲述模板" tabindex="-1">Agent 面试 · 项目讲述模板 <a class="header-anchor" href="#agent-面试-·-项目讲述模板" aria-label="Permalink to “Agent 面试 · 项目讲述模板”">​</a></h1><blockquote><p>第 8 题「结合项目」最容易空。用下面模板填你的真实经历（漫剧 / MES / 其它）。</p></blockquote><hr><h2 id="star-技术点-推荐结构" tabindex="-1">STAR + 技术点（推荐结构） <a class="header-anchor" href="#star-技术点-推荐结构" aria-label="Permalink to “STAR + 技术点（推荐结构）”">​</a></h2><table tabindex="0"><thead><tr><th>段</th><th>说什么</th><th>控制时长</th></tr></thead><tbody><tr><td>Situation</td><td>业务背景、痛点</td><td>20s</td></tr><tr><td>Task</td><td>你负责什么</td><td>15s</td></tr><tr><td>Action</td><td>链路、工具、状态、护栏</td><td>90s</td></tr><tr><td>Result</td><td>可感知结果（能量化更好）</td><td>20s</td></tr><tr><td>反射</td><td>若重来会怎么改</td><td>15s</td></tr></tbody></table><hr><h2 id="填空稿-直接改括号" tabindex="-1">填空稿（直接改括号） <a class="header-anchor" href="#填空稿-直接改括号" aria-label="Permalink to “填空稿（直接改括号）”">​</a></h2><blockquote><p>在 <strong>（项目名）</strong> 里，我们要解决 <strong>（痛点：如多模型生成任务不稳定 / 设备数据与业务脱节）</strong>。<br> 我负责 <strong>（模块：异步任务编排 / 多模型接入 / 网关采集）</strong>。<br> 实现上不是单次聊天，而是 <strong>（提交 → 执行 → 重试 → 回写）</strong> 的状态机；模型侧用 <strong>（Prompt + 结构化输出 / 工具调用）</strong>，下游接 <strong>（生图 API / 业务库 / 设备接口）</strong>。<br> 一开始就嵌了四件护栏：<strong>超时</strong>（单步 + 总超时，超时进失败/待重试/待人工）、<strong>重试</strong>（只对读安全重试）、<strong>幂等</strong>（写操作用 runId+step 一类 key）、<strong>审计</strong>（谁发起、哪步、调了啥、成败、是否人审）。<br> 结果是 <strong>（试用期交付三条产品线 / 采集打通 / 失败可定位）</strong>。<br> 若再做，我会加强 <strong>（评测集 / 费用看板 / 工具 Schema）</strong>。</p></blockquote><hr><h2 id="诚实边界-加分" tabindex="-1">诚实边界（加分） <a class="header-anchor" href="#诚实边界-加分" aria-label="Permalink to “诚实边界（加分）”">​</a></h2><p>面试官能听出来你有没有真做过。主动说清：</p><table tabindex="0"><thead><tr><th>可以说</th><th>别硬吹</th></tr></thead><tbody><tr><td>任务编排、多模型 API、状态机</td><td>「我们上了完全自主多智能体」</td></tr><tr><td>Prompt 版本化、失败重试</td><td>「完全消灭幻觉」</td></tr><tr><td>用过 Cursor / Claude 提效</td><td>「Agent 替我写完整个系统」</td></tr><tr><td>规划里要上 RAG / Tool</td><td>「生产已全量 Agent」</td></tr></tbody></table><p>标签对齐本站：<strong>[实战]</strong> 过去项目 · <strong>[实验]</strong> 实验室跑过 · <strong>[决策]</strong> 判断未测 —— 面试里同样分开说。</p><hr><h2 id="按你简历可挂的钩子" tabindex="-1">按你简历可挂的钩子 <a class="header-anchor" href="#按你简历可挂的钩子" aria-label="Permalink to “按你简历可挂的钩子”">​</a></h2><h3 id="ai-漫剧内容生产" tabindex="-1">AI 漫剧内容生产 <a class="header-anchor" href="#ai-漫剧内容生产" aria-label="Permalink to “AI 漫剧内容生产”">​</a></h3><ul><li>钩子：多模型 API、异步任务、状态回写、失败重试</li><li>Agent 表述：偏 <strong>编排 + 工具化调用</strong>；若某步有模型选工具，再提 Tool Calling</li><li>别只说「用了 AI」，说「任务怎么不丢、怎么重试、怎么验收」</li></ul><h3 id="钢瓶轻量-mes-工业" tabindex="-1">钢瓶轻量 MES / 工业 <a class="header-anchor" href="#钢瓶轻量-mes-工业" aria-label="Permalink to “钢瓶轻量 MES / 工业”">​</a></h3><ul><li>钩子：多端、采集、现场联调</li><li>Agent 表述：现场更适合 <strong>RAG 问答 + 严格禁止自动控设备</strong>；未来助手也是「建议」不是「直写 PLC」</li><li>体现判断力：工业场景的边界意识</li></ul><h3 id="ai-coding-提效" tabindex="-1">AI Coding 提效 <a class="header-anchor" href="#ai-coding-提效" aria-label="Permalink to “AI Coding 提效”">​</a></h3><ul><li>钩子：Cursor 工作流、Code Review、小 Bug 闭环</li><li>表述：人定范围与验收，Agent 加速编辑；合入前有测试/人审</li></ul><hr><h2 id="常见追问速答" tabindex="-1">常见追问速答 <a class="header-anchor" href="#常见追问速答" aria-label="Permalink to “常见追问速答”">​</a></h2><ul><li>「和 ChatGPT 网页差在哪？」→ 我们有状态、权限、业务 API，可审计。</li><li>「效果怎么量化？」→ 成功率、重试次数、人工介入率、费用（有数说数）。</li><li>「最大踩坑？」→ 准备 1 个真实坑：超时未重试 / 状态不一致 / 提示词无版本…</li><li>「可靠性一开始怎么设计的？」→ 背四件套：超时、重试（读写分开）、幂等 key、审计字段；多 Agent 再说总超时 vs 单步 timeout。</li></ul><hr><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to “练习”">​</a></h2><p>对着手机录 <strong>2 分钟</strong> 项目讲述；听有没有：状态机、护栏、结果、边界。缺哪补哪。</p>',27)])])}const p=r(d,[["render",n]]);export{b as __pageData,p as default};
